    n = tl.program_id(1).to(tl.int64)
    src = cols + n * cols_s0
    for c0 in range(0, 1100, BLOCK):
        c = c0 + tl.arange(0, BLOCK)
        cm = c < 1100
        acc = tl.zeros([BLOCK], dtype=tl.float32)
        for r in tl.static_range(1):
            j = r  # the only tap
            i = t - j
            ok = (i >= 0) & (i < Li)
            v = tl.load(src + i * cols_s1 + (c * 1 + j) * cols_s2, mask=cm & ok, other=0.0)
            acc = acc + v.to(tl.float32)
        tl.store(y + (n * Lo + t) * 1100 + c, acc.to(tl.float16), mask=cm)
